def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    dd = 0
    for i in range(n):
        a, b = history[i]
        if a == 'D':
            my_d += 1
        if b == 'D':
            opp_d += 1
        if a == 'D' and b == 'D':
            dd += 1

    start5 = n - 5
    if start5 < 0:
        start5 = 0
    recent5_opp_d = 0
    recent5_opp_c = 0
    for i in range(start5, n):
        if history[i][1] == 'D':
            recent5_opp_d += 1
        else:
            recent5_opp_c += 1

    start10 = n - 10
    if start10 < 0:
        start10 = 0
    recent10_opp_c = 0
    for i in range(start10, n):
        if history[i][1] == 'C':
            recent10_opp_c += 1

    opp_d_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    opp_c_streak = 0
    for i in reversed(range(n)):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    my_d_streak = 0
    for i in reversed(range(n)):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    start = n - 9
    if start < 0:
        start = 0
    recent_forgiven = 0
    recent_punished = 0
    for i in range(start, n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                recent_forgiven += 1
            elif history[i + 1][1] == 'D':
                recent_punished += 1

    if n >= 2 and opp_d == n:
        return 'D'
    if n >= 4 and opp_d >= n - 1:
        return 'D'
    if n >= 10 and opp_d * 5 >= n * 3 and recent5_opp_d >= 3:
        return 'D'
    if n >= 20 and opp_d * 2 >= n and recent5_opp_d >= 4:
        return 'D'

    if opp_d == 0 and n >= 12:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if (opp_d <= max(6, n // 6) and opp_d_streak <= 2) or (recent10_opp_c >= 6 and opp_d_streak <= 2) or (opp_d_streak == 1 and my_d_streak >= 2):
                return 'C'
            if dd >= 12 and opp_d * 2 <= n and rng.random() < 0.3:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_d <= max(8, n // 4) and opp_d_streak <= 2 and recent5_opp_c >= 2:
                return 'C'
            return 'D'

        return 'D'

    if my_last == 'D':
        forgiving = (
            opp_c_streak >= 2 or
            (recent_forgiven >= 1 and recent_punished == 0 and opp_d <= max(8, n // 4)) or
            opp_d == 0
        )
        high_d = opp_d * 2 >= n and recent5_opp_d >= 2
        if forgiving or high_d:
            return 'D'
        return 'C'

    if n >= 96 and recent5_opp_d == 0 and opp_d * 3 <= n * 2:
        return 'D'

    if recent_forgiven >= 2 and recent_punished == 0 and opp_d <= max(8, n // 4):
        return 'D'

    if opp_d * 2 >= n and recent5_opp_d >= 2:
        return 'D'

    return 'C'
